#!/usr/bin/env python3
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
checks=[]
def text(path): return (ROOT/path).read_text(encoding='utf-8')
def check(label,condition):
    checks.append((label,bool(condition)))
    print(('PASS' if condition else 'FAIL')+' - '+label)

case=text(Path('src/main/java/com/example/editor/transformation/testing/TransformationTestCase.java'))
repo=text(Path('src/main/java/com/example/editor/transformation/testing/persistence/JsonTransformationTestCaseRepository.java'))
service=text(Path('src/main/java/com/example/editor/transformation/testing/TransformationTestService.java'))
controller=text(Path('src/main/java/com/example/editor/transformation/testing/TransformationTestController.java'))
quick=text(Path('src/main/java/com/example/editor/transformation/quickfix/TransformationQuickFixService.java'))
quick_controller=text(Path('src/main/java/com/example/editor/transformation/quickfix/TransformationQuickFixController.java'))
app=text(Path('src/main/java/com/example/editor/transformation/TransformationApplicationService.java'))
frontend=text(Path('frontend/src/transformation-designer/TransformationTestingPanel.tsx'))
designer=text(Path('frontend/src/transformation-designer/TransformationDesigner.tsx'))
qpanel=text(Path('frontend/src/transformation-designer/TransformationQuickFixPanel.tsx'))
api=text(Path('frontend/src/transformation-designer/api.ts'))
types=text(Path('frontend/src/transformation-designer/types.ts'))
runtime=text(Path('src/main/java/com/example/editor/transformation/text/CanonicalTextGenerationRuntime.java'))
css=text(Path('frontend/src/transformation-designer/transformation-designer.css'))

check('test cases are versioned canonical artifacts','CURRENT_SCHEMA_VERSION = "1.1"' in case and 'SUPPORTED_SCHEMA_VERSIONS = Set.of("1.0", CURRENT_SCHEMA_VERSION)' in case)
check('test cases persist source text and canonical source models','CanonicalModelDocument sourceModel' in case and 'String sourceText' in case)
check('test cases persist expected model and M2T artifacts','CanonicalModelDocument expectedModel' in case and 'TransformationExpectedArtifact' in case)
check('test repository reuses canonical atomic document store','CanonicalDocumentStore<TransformationTestCase>' in repo and 'transformation.test-case' in repo)
check('test repository uses dedicated directory and suffix','getTestDirectory()' in repo and 'getTestFileSuffix()' in repo)
check('test CRUD uses ETags','HttpHeaders.ETAG' in controller and 'HttpHeaders.IF_MATCH' in controller)
check('test runner supports one case and complete suite','runOne(' in service and 'runAll(' in service)
check('M2M test coverage forces detailed trace only in memory','forceDetailedTrace' in service and 'new TransformationTracePolicy(true, true)' in service)
check('coverage counts rule trace links','trace.links()' in service and 'ruleHits' in service)
check('coverage counts binding traces','trace.bindingTraces()' in service and 'bindingHits' in service)
check('M2T coverage uses generated artifact rule ids','result.artifacts()' in service and 'rules.merge(item.ruleId()' in service)
check('semantic mismatches remain FAIL rather than runtime ERROR','TransformationTestStatus.FAIL' in service and 'Canonical model result differs' in service)
check('transformation deletion fails closed while tests exist','hasPersistedTests' in app and 'Delete the transformation test cases before deleting the transformation' in app)
check('quick fixes are side-effect-free proposals','proposedTransformation' in text(Path('src/main/java/com/example/editor/transformation/quickfix/TransformationQuickFix.java')) and '@PostMapping' in quick_controller)
check('quick fixes support explicit type conversion','TYPE_CONVERSION_REQUIRED' in quick and 'conversionFix' in quick)
check('quick fixes support explicit collection reduction','COLLECTION_REDUCTION_REQUIRED' in quick and 'TransformationCollectionMode.FIRST' in quick)
check('quick fixes can remove obsolete mappings','UNKNOWN_SOURCE_ATTRIBUTE' in quick and 'removeBrokenBindingFix' in quick)
check('required-property mapping suggestion is conservative','candidates.size() != 1' in quick and 'sameType' in quick and 'safeAutomatic' not in quick)
check('frontend persists captured expected results','Preview and capture expected' in frontend and 'createTransformationTest' in frontend)
check('frontend executes persisted suite and renders rule coverage','runTransformationTestSuite' in frontend and 'ruleCovered' in frontend)
check('frontend renders binding coverage','bindingCovered' in frontend)
check('frontend quick fixes require explicit Apply proposal','Apply proposal' in qpanel and 'proposedTransformation' in qpanel)
check('guided and manual review share testing panel','const testing = <TransformationTestingPanel' in designer and '{testing}' in designer)
check('frontend API exposes transformation test suite','/tests/run' in api and 'listTransformationTests' in api)
check('frontend API exposes side-effect-free quick fixes','/api/transformations/quick-fixes' in api)
check('frontend types carry coverage and quick fix contracts','TransformationCoverageReport' in types and 'TransformationQuickFixReport' in types)
check('Fix21 M2T token alphabet remains preserved','[A-Za-z0-9._:-]' in runtime)
check('transformation CSS remains below shared 1400-character ceiling',max(map(len,css.splitlines()),default=0)<=1400)
check('backend unit tests cover persistent coverage',Path(ROOT/'src/test/java/com/example/editor/transformation/testing/TransformationTestServiceTests.java').exists())
check('backend unit tests cover quick fix immutability',Path(ROOT/'src/test/java/com/example/editor/transformation/quickfix/TransformationQuickFixServiceTests.java').exists())
check('frontend contract test covers testing and quick fixes','persistent tests coverage and quick fixes' in text(Path('frontend/src/transformation-designer/TransformationDesignerContract.test.ts')))

failed=[label for label,ok in checks if not ok]
print(f'TRANSFORMATION_TESTING_QUICKFIX_FIX22={len(checks)-len(failed)}/{len(checks)} PASS' if not failed else f'TRANSFORMATION_TESTING_QUICKFIX_FIX22={len(checks)-len(failed)}/{len(checks)} FAIL')
if failed: raise SystemExit(1)
